    private val aliasChunks =
        arrayOf(
            ALIAS_CHUNK_000,
            ALIAS_CHUNK_001,
            ALIAS_CHUNK_002,
            ALIAS_CHUNK_003,
            ALIAS_CHUNK_004,
            ALIAS_CHUNK_005,
            ALIAS_CHUNK_006,
            ALIAS_CHUNK_007,
            ALIAS_CHUNK_008,
            ALIAS_CHUNK_009,
        )
    val terms: Set<String> =
        termChunks
            .asSequence()
            .flatMap { it.lineSequence() }
            .filter(String::isNotBlank)
            .toSet()

    /** Unambiguous single-word MeSH entry-term aliases. */
    val aliases: Map<String, String> =
        aliasChunks
            .asSequence()
            .flatMap { it.lineSequence() }
            .filter(String::isNotBlank)
            .associate { line ->
                val (alias, canonical) = line.split('\t', limit = 2)
                alias to canonical
            }
}
